// A slot result is committed once; its queued effects wait for this presentation.
let luckySlotHost=null,luckySlotRun=null,luckySlotTimer=null;
function luckyClearSlotVisual(){clearTimeout(luckySlotTimer);luckySlotTimer=null;luckySlotHost?.remove();luckySlotHost=null;luckySlotRun=null;}
function luckyPositionSlot(){if(!luckySlotHost)return;const anchor=luckySlotHost.querySelector('.slot-reveal-anchor'),rect=document.querySelector('.arena')?.getBoundingClientRect?.();if(anchor){anchor.style.left=(rect?rect.left+rect.width/2:window.innerWidth/2)+'px';anchor.style.top=(rect?rect.top+rect.height/2:window.innerHeight/2)+'px';}}
function luckyPresentSlot(r){const p=r?.lucky?.slotPresentation;if(!p||!canPresentBattleCards())return;if(luckySlotHost&&luckySlotRun===r)return;
luckyClearSlotVisual();luckySlotRun=r;
let sample=document.querySelector('.hand .card'),probe=null;if(!sample&&!globalThis.ASHBOUND_HEADLESS){probe=document.createElement('div');probe.className='cards hand';probe.style.cssText='position:absolute;visibility:hidden;pointer-events:none;left:-10000px;top:0';probe.innerHTML=presentationSnapshot(p.seen[0]??LUCKY_IDS.spin);(document.getElementById('game-shell')||document.body).append(probe);sample=probe.querySelector('.card');}
const bounds=sample?.getBoundingClientRect?.(),matrix=sample&&typeof getComputedStyle==='function'?getComputedStyle(sample).transform:'none',parts=matrix?.startsWith('matrix(')?matrix.slice(7,-1).split(',').map(Number):null,hoverScale=parts?Math.hypot(parts[0],parts[1]):1,observedScale=bounds?.width&&sample?.offsetWidth?bounds.width/sample.offsetWidth/hoverScale:0;
const scale=observedScale||(typeof displayPrefs==='object'?displayPrefs.ui*displayPrefs.zoom/10000:1),logicalWidth=sample?.offsetWidth||166,logicalHeight=sample?.offsetHeight||280,width=logicalWidth*scale,height=logicalHeight*scale,overlap=Math.min(width*.75,Math.max(0,(p.seen.length*width-window.innerWidth*.94)/Math.max(1,p.seen.length-1)));
const host=document.createElement('div');luckySlotHost=host;host.className='slot-reveal-overlay';host.style.setProperty('--slot-scale',scale);host.style.setProperty('--slot-logical-width',logicalWidth+'px');host.style.setProperty('--slot-logical-height',logicalHeight+'px');host.style.setProperty('--slot-card-width',width+'px');host.style.setProperty('--slot-card-height',height+'px');host.style.setProperty('--slot-overlap',overlap+'px');host.setAttribute('role','status');host.setAttribute('aria-label','スロット判定：'+(p.success?'成功':'失敗'));
host.innerHTML='<div class="slot-reveal-anchor"><div class="slot-reveal-stage"><div class="slot-reveal-cards" style="--slot-count:'+Math.max(1,p.seen.length)+'">'+p.seen.map(id=>'<div class="slot-reveal-item '+(cardCategories(C[id]).includes(p.kind)?'slot-match':'slot-miss')+'"><div class="slot-reveal-flip"><div class="slot-reveal-back">♧</div><div class="slot-reveal-front">'+presentationSnapshot(id)+'</div></div></div>').join('')+'</div><strong class="slot-reveal-result '+(p.success?'success':'failed')+'">'+(p.success?'SUCCESS':'FAILED')+'</strong></div></div>';
document.body.append(host);
if(sample&&typeof getComputedStyle==='function'){for(const selector of ['.card','.art','.cost','.card h3','.card p','.card small','.lucky-card-art']){const source=selector==='.card'?sample:sample.querySelector(selector.replace('.card ',''));if(!source)continue;const style=getComputedStyle(source);host.querySelectorAll('.slot-reveal-front '+selector).forEach(el=>{for(const key of ['font-size','line-height','padding','margin','border-radius'])el.style.setProperty(key,style.getPropertyValue(key));if(['.art','.cost','.lucky-card-art'].includes(selector))for(const key of ['width','height'])el.style.setProperty(key,style.getPropertyValue(key));});}}probe?.remove();luckyPositionSlot();
luckySlotTimer=setTimeout(()=>{if(luckySlotRun!==r)return;luckyClearSlotVisual();if(S.run!==r||r.mode!=='battle')return;r.lucky.slotPresentation=null;luckyPump(r);},2500);
}
const luckySlotRenderBase=render;render=function(){luckySlotRenderBase();const r=S.run;if(page==='battle'&&r?.lucky?.slotPresentation)luckyPresentSlot(r);else if(luckySlotHost)luckyClearSlotVisual();};
window.addEventListener('resize',luckyPositionSlot);
if(!globalThis.ASHBOUND_HEADLESS)render();
